# Index Rebuild Scheduler demo: trigger evaluation, window picking, blue-green flip.
TRAFFIC={0:5,1:3,2:2,3:2,4:4,12:90,13:95}  # hour -> qps
INDEX={"staleness_h":30,"corrupt":False}
def should_rebuild(idx):
    return idx["staleness_h"]>24 or idx["corrupt"]
def best_window():
    return min(TRAFFIC,key=TRAFFIC.get)
def rebuild():
    if not should_rebuild(INDEX): return "no rebuild needed"
    w=best_window()
    new="index-v2(built off-traffic)"
    verified=True  # health battery
    return "rebuilt in window %02d:00, verified=%s, traffic flipped to %s"%(w,verified,new)
print(rebuild())

